class Solution {
public:
 int countIslands(vector<vector<int>>& grid,int k){int m=grid.size(),n=grid[0].size(),ans=0;int dr[4]={1,-1,0,0},dc[4]={0,0,1,-1};
  for(int i=0;i<m;++i)for(int j=0;j<n;++j)if(grid[i][j]){long long sum=0;queue<pair<int,int>>q;q.push({i,j});sum+=grid[i][j];grid[i][j]=0;
   while(!q.empty()){auto p=q.front();q.pop();for(int z=0;z<4;++z){int x=p.first+dr[z],y=p.second+dc[z];if(x>=0&&x<m&&y>=0&&y<n&&grid[x][y]){sum+=grid[x][y];grid[x][y]=0;q.push({x,y});}}}if(sum%k==0)++ans;
  }return ans;
 }
};
